  function noticeHtml(){return state.error?`<div class="notice"><span class="notice-text">${escapeHtml(state.error)}</span><button data-action="retry">重试</button></div>`:''}
  function syncNotice(){const main=document.querySelector('.main');if(!main)return;const old=main.querySelector(':scope > .notice');if(!state.error){old?.remove();return}const html=noticeHtml();if(old)old.outerHTML=html;else main.insertAdjacentHTML('afterbegin',html)}
