  function meter(label,val,text,cls=''){const c=val>=90?'bad':val>=75?'warn':cls;return `<div class="metric"><div class="metric-top"><span>${label}</span><b>${escapeHtml(text)}</b></div><div class="bar ${c}"><span style="width:${clamp(val).toFixed(1)}%"></span></div></div>`}
